export interface AlwaysHandle {
    /** Unique task ID */
    readonly id: number;

    /** Stops and unregisters the callback */
    stop(): void;

    /** Pauses execution without unregistering */
    pause(): void;

    /** Resumes a paused callback */
    resume(): void;

    /** Resets the elapsed timer, invocation counter, and interval accumulator */
    reset(): void;

    /** Whether the task is currently active */
    readonly isRunning: boolean;

    /** Whether the task is currently paused */
    readonly isPaused: boolean;

    /** Total number of successful invocations */
    readonly count: number;

    /** Total active time elapsed in ms */
    readonly elapsed: number;
}

export interface AlwaysContext {
    /** Total active elapsed time in milliseconds */
    readonly elapsed: number;
    /** 1-based invocation count */
    readonly count: number;
    /** Interval-adjusted delta time in ms (accumulates over skipped frames) */
    readonly dt: number;
    /** Raw frame delta time in ms */
    readonly frameDt: number;
    /** Convenience helper to stop this task */
    stop(): void;
    /** Pause this task */
    pause(): void;
    /** Resume this task */
    resume(): void;
}

// Throttled to run at most every 100ms (10 times per second)
scene.always(() => {
    fpsDisplay.textContent = `${engine.currentFps} FPS`;
    harmonicsBadge.textContent = `${activeCount} Harmonics`;
}, { interval: 100 });

// Runs every 50ms, dt is ~50ms (not 16ms), ensuring accurate numeric integration
entity.always((time, dt, ctx) => {
    particle.position.x += velocity.x * (dt / 1000);
    // ctx.frameDt is still available if raw frame delta is needed
}, { interval: 50 });

// Without phase: 'post', camera reads tip position BEFORE tip moves this frame (1-frame lag)
// With phase: 'post', camera reads the final, fresh position in the exact same frame!
scene.always(
    () => controller.follow(satellite.localToWorld(satellite.getTip()), { damping: 12 }),
    { phase: 'post' }
);

// Pattern 1: Return false directly from the callback
entity.always((time, dt) => {
    entity.position.x += speed * dt;
    if (entity.position.x >= targetX) {
        return false; // Automatically unregisters!
    }
});

// Pattern 2: Declarative 'until' predicate
entity.always(pulseAnimation, {
    until: () => entity.position.y > 600
});

// Pattern 3: Self-stopping via context
entity.always((time, dt, ctx) => {
    if (collisionDetected) {
        ctx.stop();
    }
});

// Screen shake lasts exactly 600ms, then stops automatically
scene.always((time, dt) => {
    camera.offset.x = (Math.random() - 0.5) * intensity;
    camera.offset.y = (Math.random() - 0.5) * intensity;
}, { duration: 600 });

// Spawns a shockwave 500ms after impact
scene.always(() => {
    shockwave.radius += dt * 0.4;
}, { delay: 500, duration: 1500 });

// Only computes particle kinematics when this entity is visible on screen
particles.always(() => computeParticles(), { onlyWhenVisible: true });

// When entity.destroy() or entity.dispose() is called,
// all registered updaters are automatically purged to prevent memory leaks.

const controller = new AbortController();

scene.always(networkSync, { signal: controller.signal });

// Later, on route change or modal close:
controller.abort();

